import numpy as np
from scipy.optimize import least_squares
y=dv_dt
basis=[np.ones_like(t),x,v,np.sin(v),x*x,v*v,x*v]
def build(w,nh):
    cols=list(basis)
    for k in range(1,nh+1):
        cols+=[np.cos(k*w*t),np.sin(k*w*t)]
    return np.column_stack(cols)
def res(p,nh):
    Z=build(p[0],nh); c=np.linalg.lstsq(Z,y,rcond=None)[0]; return Z@c-y
for nh in [1,2,3]:
    best=None
    for w0 in np.linspace(0.2,1.2,21):
        r=least_squares(res,[w0],args=(nh,))
        e=np.mean(r.fun**2)/np.var(y)
        if best is None or e<best[0]: best=(e,r.x[0])
    print(nh,best)
